        const halfW = (anchorData.w || 80) / 2;
        const halfH = (anchorData.h || 28) / 2;
        if (pos === 'top') { ox = 0; oy = -halfH; }
        else if (pos === 'bottom') { ox = 0; oy = halfH; }
        else if (pos === 'left') { ox = -halfW; oy = 0; }
